CREATE OR REPLACE FUNCTION public.announcement_json(a public.announcements)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'id', a.id,
    'releaseId', a.release_id,
    'releaseTitle', (select r.title from public.releases r where r.id = a.release_id),
    'releaseStatus', (select r.status from public.releases r where r.id = a.release_id),
    'kind', a.kind,
    'title', a.title,
    'body', a.body,
    'items', a.items,
    'createdAt', a.created_at,
    'createdBy', a.created_by,
    'publishAt', a.publish_at,
    'withdrawnAt', a.withdrawn_at,
    'withdrawnBy', a.withdrawn_by);
$function$;

grant execute on function public.announcement_json(a public.announcements) to service_role;
